// ============================================================
// VITAL VISION SHOP — BRAND INTELLIGENCE LOADER
// Built from: config/product-library.md, config/brand-voice.md,
//             config/compliance-rules.md,
//             vital-vision-system/brand/positioning-and-compliance.md
// n8n is the runtime. Claude Code is the build/maintenance layer.
// Update this node when brand/product/compliance rules change.
// ============================================================

const PRODUCTS = {
  'Inner Bloom': {
    category: 'Digestive wellness, gut balance, daily self-care ritual',
    corePain: 'I eat and my stomach feels like a balloon.',
    safePositioning: 'Designed to support daily digestive wellness, gut balance, digestive comfort, and overall wellness as part of a consistent self-care routine.',
    bestFormats: 'Pain recognition Reels, Q&A Stories, Educational carousels, Morning routine content',
    approvedCTA: 'Comment BLOOM for the routine. / Explore Inner Bloom. / Start your Inner Bloom ritual.',
    url: '/products/advanced-probiotic-formula'
  },
  'Inner Calm': {
    category: 'Calm routine, magnesium support, evening wellness ritual',
    corePain: 'My body feels busy even when my day is over.',
    safePositioning: 'Designed to support a calm routine, relaxation, daily balance, and overall wellness as part of an evening self-care ritual.',
    bestFormats: 'Evening routine Reels, Calm checklist Stories, Educational posts about consistency',
    approvedCTA: 'Comment CALM for the evening ritual. / Explore Inner Calm. / Save this for tonight.',
    url: '/products/inner-calm-magnesium-glycinate'
  },
  'Inner Balance': {
    category: 'Daily multivitamin, foundational wellness, daily self-care routine',
    corePain: 'I want a wellness routine, but I do not want 10 different bottles.',
    safePositioning: 'Designed to support daily wellness, overall wellbeing, and a consistent self-care routine.',
    bestFormats: 'Morning routine content, Simple wellness checklist, Educational carousel about routine simplicity',
    approvedCTA: 'Comment BALANCE for the daily ritual. / Explore Inner Balance. / Start with one simple daily wellness step.',
    url: '/products/inner-balance-complete-multivitamin'
  },
  'Inner Grow': {
    category: 'Hair, skin, and nails support, beauty from within, daily beauty wellness',
    corePain: 'I am doing beauty routines outside, but I want support from within.',
    safePositioning: 'Designed to support hair, skin, and nails as part of a consistent beauty wellness routine.',
    bestFormats: 'GRWM content, Beauty ritual Reels, Q&A about beauty from within',
    approvedCTA: 'Comment GROW for the beauty ritual. / Explore Inner Grow. / Start your beauty from within routine.',
    url: '/products/inner-grow-hair-skin-and-nails-support'
  }
};

const product = $json.product || '';
const productCtx = PRODUCTS[product] || {};

if (!productCtx.category) {
  throw new Error('Unknown product: "' + product + '". Must be one of: Inner Bloom, Inner Calm, Inner Balance, Inner Grow');
}

return [{
  json: {
    ...$json,
    product_category: productCtx.category,
    product_core_pain: productCtx.corePain,
    product_safe_positioning: productCtx.safePositioning,
    product_best_formats: productCtx.bestFormats,
    product_approved_cta: productCtx.approvedCTA,
    product_url: productCtx.url
  }
}];

// ============================================================
// VITAL VISION SHOP — COMPLIANCE VALIDATOR
// Checks content for forbidden medical/drug/disease claims.
// Handles two input paths:
//   1. Bypass path (existing_script set, Anthropic skipped):
//      uses $json.existing_script as the content to validate.
//   2. Anthropic path (existing_script was empty):
//      extracts generated text from $json.content[0].text.
// AUTO_PUBLISH=false — failed items are never approved automatically.
// Source: config/compliance-rules.md + positioning-and-compliance.md
// ============================================================

const FORBIDDEN_TERMS = [
  // Disease/condition treatment claims
  'cures ', 'cure ', ' cures', ' cure\n', 'treats ', ' treats ', 'heals ', 'heals your',
  'fix your gut', 'fixes your', 'fix your', 'prevents disease', 'prevent disease',
  'diagnoses', 'reverse aging', 'reverses aging', 'eliminates bloating',
  'eliminate gas', 'eliminates gas',
  // Guaranteed outcome
  'guaranteed results', 'guaranteed result', 'guarantees comfort', 'guarantee results',
  // Specific condition claims
  'no more bloating', 'stop bloating', 'grow hair fast', 'stop hair loss',
  'cure anxiety', 'cures anxiety', 'treat insomnia', 'treats insomnia',
  'cure insomnia', 'treat depression', 'treats depression',
  // Regulatory violations
  'clinically proven', 'fda approved', 'fda-approved', 'no side effects',
  'scientifically proven',
  // Other forbidden
  'boost immunity guaranteed', 'balances your hormones', 'hormone balance guaranteed',
  'burns fat', 'melts belly fat', 'reduces inflammation',
  'detoxes your body', 'detox your body', 'fixes leaky gut',
  'treats acne', 'clears acne', 'anti-aging cure',
  'doctor recommended', 'physician recommended'
];

// Handle both input paths:
// - Anthropic path: content in $json.content[0].text (Anthropic Messages API format)
// - Bypass path (existing script): content in $json.existing_script
const fromAnthropic = $json.content && $json.content[0] && $json.content[0].text;
const generated = fromAnthropic
  ? $json.content[0].text
  : ($json.existing_script || '');

if (!generated) {
  throw new Error('No content to validate. Script / Caption Draft is empty and Anthropic returned no content. Check the Route node and Anthropic credentials.');
}

const lowerContent = generated.toLowerCase();
const violations = FORBIDDEN_TERMS.filter(term =>
  lowerContent.includes(term.toLowerCase())
);

const compliancePass = violations.length === 0;
const complianceFlag = compliancePass ? 'PASS' : 'BLOCKED';
const complianceNote = compliancePass
  ? 'PASS — No forbidden terms detected'
  : 'BLOCKED — Forbidden terms detected: ' + violations.join(' | ');

return [{
  json: {
    row_number: $json.row_number,
    product: $json.product,
    content_type: $json.content_type,
    funnel_stage: $json.funnel_stage,
    hook: $json.hook,
    platform_group: $json.platform_group,
    source_competitor: $json.source_competitor,
    angle: $json.angle,
    creator_persona: $json.creator_persona,
    generated_content: generated,
    compliance_pass: compliancePass,
    compliance_flag: complianceFlag,
    compliance_note: complianceNote
  }
}];
